}
const LINK_INSIDE_PAREN_RE = /\[([^\]]+)\]\(([^)]+)\)/g;
function trimTrailingSpaceAndPeriod(s) {
    let end = s.length;
    while (end > 0 && /[\s.]/.test(s[end - 1])) {
        end--;
    }
    return end;
}
// Walks backward counting paren depth (a naive `\(([^()]*)\)` regex fails since markdown links themselves contain `()`).
