139	    }
140	}
141	export function segmentStatements(content) {
142	    const lines = content.split(/\r?\n/);
143	    const accumulator = new StatementAccumulator();
144	    for (let i = 0; i < lines.length; i++) {
145	        i = accumulator.processLine(lines, i);
146	    }
147	    return accumulator.finish();
148	}
149	const SECTION_RULES = [
150	    { match: /problem\s*statement/i, category: "background" },
151	    { match: /background/i, category: "background" },
152	    { match: /context\b/i, category: "background" },
153	    { match: /research/i, category: "background" },
154	    { match: /personas?/i, category: "background" },
155	    { match: /implementation\s*phases?/i, category: "background" },
156	    { match: /vision/i, category: "vision" },
157	    {
158	        match: /goals?\s*[&/]\s*non[-\s]?goals?|non[-\s]?goals?/i,
159	        category: "vision",
160	    },
161	    { match: /clarif/i, category: "clarification" },
162	    { match: /open\s*questions?/i, category: "open-question" },
163	    {
164	        match: /limitations?|known\s*gotchas?|out[-\s]?of[-\s]?scope/i,
165	        category: "limitation",
166	    },
167	    {
168	        match: /rationale|why\b|alternatives?\s*(considered)?|consequences/i,
169	        category: "rationale",
170	    },
171	];
