16	import type {ContextConfig} from './conversationContext.js';
17	import {
18	  shouldContinueToolLoop,
19	  collectText,
20	  buildToolCallMessages,
21	  collectToolCalls,
22	  extractStopReason,
23	  extractUsage,
24	  addUsage,
25	} from './orchestratorHelpers.js';
26	import {appendEntry, commitStreamingEntries} from './entryMutations.js';
27	import {log} from '../shared/logger.js';
28	
29	const DEFAULT_MAX_TOOL_ROUNDS = 5;
30	
31	export interface OrchestratorHooks {
32	  beforeSession?: (session: ChatSession) => Promise<void>;
33	  afterSession?: (session: ChatSession) => Promise<void>;
34	  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
35	  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
36	  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
37	  afterModelResponse?: (session: ChatSession, responseText: string, usage?: UsageMetadata) => Promise<void>;
38	  onError?: (session: ChatSession, error: Error) => Promise<void>;
39	  /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
40	  beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
41	  /** Fires when the model asks for a tool round the budget refuses, after the last provider call and before afterModelResponse; a returned string reaches the user as the turn's closing text, and the engine writes none of its own (see specs/hal-engine-tool-budget/spec.md). */
42	  onToolBudgetExhausted?: (session: ChatSession, budget: ToolBudgetInfo) => Promise<string | undefined>;
43	}
44	
45	export interface ToolBudgetInfo {
46	  maxToolRounds: number;
47	  requestedTools: string[];
48	}
49	
50	type BeforeToolCall = NonNullable<OrchestratorHooks['beforeToolCall']>;
51	type OnToolBudgetExhausted = NonNullable<OrchestratorHooks['onToolBudgetExhausted']>;
52	
53	export const TOOL_BUDGET_EXHAUSTED = 'tool_budget_exhausted';
54	
55	export interface ChatOrchestrator {
56	  processMessage(session: ChatSession): Promise<string>;
57	  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
58	}
59	
60	export interface ChatOrchestratorOptions {
61	  maxToolRounds?: number;
62	  contextConfig?: Partial<ContextConfig>;
63	  promptBuilderOptions?: PromptBuilderOptions;
64	  hooks?: OrchestratorHooks;
65	  sessionStore?: SessionStore;
66	}
67	
68	interface ToolExecutionResult {
69	  clientMessages: OutgoingMessage[];
70	  suppressOutput: boolean;
71	}
72	export function createChatOrchestrator(
73	  provider: AIProvider,
74	  promptBuilder: PromptBuilder,
75	  toolRegistry?: ToolRegistry,
76	  options?: ChatOrchestratorOptions
77	): ChatOrchestrator {
78	  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
79	  const contextConfig = createContextConfig(options?.contextConfig);
80	  const toolInstructions = toolRegistry?.getPromptInstructions();
81	  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
82	  const tools = toolRegistry?.getDefinitions();
83	  const hooks = options?.hooks;
84	  const sessionStore = options?.sessionStore;
85	
86	  return {
87	    async processMessage(session: ChatSession): Promise<string> {
88	      return collectText(this.processMessageStream(session));
89	    },
90	
91	    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
92	      try {
93	        if (hooks?.beforeSession) await hooks.beforeSession(session);
94	
95	        let userMessage = lastUserContent(session);
96	
97	        if (hooks?.beforeUserInput) {
98	          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
